const fs = require('fs');
const { Pool } = require('pg');
const csv = require('csv-parser');

const pool = new Pool({
  host: 'localhost',
  port: 5432,
  database: 'myapp',
  user: 'postgres',
  password: 'postgres'
});

const results = [];

fs.createReadStream('users.csv')
  .pipe(csv())
  .on('data', (row) => {
    results.push(row);
  })
  .on('end', async () => {
    const client = await pool.connect();
    try {
      for (const row of results) {
        // Build and execute query directly
        const query = `INSERT INTO users (id, name, email, phone) VALUES (${row.id}, '${row.name}', '${row.email}', '${row.phone}')`;
        await client.query(query);
      }
      console.log('Import complete');
    } finally {
      client.release();
      pool.end();
    }
  });
